function check(input, actual, expected) {
  const [rains] = input;
  if (!Array.isArray(actual)) return false;
  // The reference returns [] only when no plan exists.
  if (expected.length === 0) return actual.length === 0;
  if (actual.length !== rains.length) return false;
  const full = new Set();
  for (let i = 0; i < rains.length; i++) {
    if (rains[i] > 0) {
      if (actual[i] !== -1 || full.has(rains[i])) return false;
      full.add(rains[i]);
    } else {
      if (!Number.isInteger(actual[i]) || actual[i] < 1 || actual[i] > 1000000000) return false;
      full.delete(actual[i]);
    }
  }
  return true;
}

