function avoidFlood(rains) {
  const n = rains.length;
  const answer = new Array(n).fill(-1);
  const lastRain = new Map();
  const nextDry = Array.from({ length: n + 1 }, (_, day) => day);

  const findDry = (day) => {
    while (nextDry[day] !== day) {
      nextDry[day] = nextDry[nextDry[day]];
      day = nextDry[day];
    }
    return day;
  };

  for (let day = 0; day < n; day++) {
    const lake = rains[day];
    if (lake === 0) {
      answer[day] = 1;
      continue;
    }
    if (lastRain.has(lake)) {
      const dryDay = findDry(lastRain.get(lake) + 1);
      if (dryDay === day) {
        return [];
      }
      answer[dryDay] = lake;
      nextDry[dryDay] = dryDay + 1;
    }
    nextDry[day] = day + 1;
    lastRain.set(lake, day);
  }
  return answer;
}

