function avoidFlood(rains) {
  // Backtracking: on each dry day try drying every lake that is currently full.
  const plan = [];
  const search = (day, full) => {
    if (day === rains.length) return true;
    const lake = rains[day];
    if (lake > 0) {
      if (full.has(lake)) return false;
      plan.push(-1);
      if (search(day + 1, new Set([...full, lake]))) return true;
      plan.pop();
      return false;
    }
    if (full.size === 0) {
      plan.push(1);
      if (search(day + 1, full)) return true;
      plan.pop();
      return false;
    }
    for (const choice of full) {
      plan.push(choice);
      const rest = new Set(full);
      rest.delete(choice);
      if (search(day + 1, rest)) return true;
      plan.pop();
    }
    return false;
  };
  return search(0, new Set()) ? plan : [];
}

