function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const length = large ? 2000 : pick(1, 10);
  const poolSize = large ? pick(5, 400) : pick(1, 4);
  const pool = Array.from({ length: poolSize }, (_, i) => (rand() < 0.3 ? pick(1, 1000000000) : i + 1));
  const dryChance = large ? 0.2 + rand() * 0.3 : 0.3 + rand() * 0.2;
  // Repaired inputs always have a plan: whenever a lake would flood with no free dry day
  // after its last rain, a dry day is added right before the rain.
  const repair = rand() < (large ? 0.75 : 0.5);
  const rains = [];
  const lastRain = new Map();
  const freeDry = [];
  while (rains.length < length) {
    if (rand() < dryChance) {
      freeDry.push(rains.length);
      rains.push(0);
      continue;
    }
    const lake = pool[Math.floor(rand() * poolSize)];
    if (repair && lastRain.has(lake)) {
      const at = freeDry.findIndex(d => d > lastRain.get(lake));
      if (at >= 0) freeDry.splice(at, 1);
      else if (rains.length + 1 < length) rains.push(0);
      else continue;
    }
    lastRain.set(lake, rains.length);
    rains.push(lake);
  }
  return [rains];
}
